    int a1, a2, a3;
    cin >> a1 >> a2 >> a3;
    int b1, b2, b3;
    cin >> b1 >> b2 >> b3;

    int min_total = min(a1, b1 + b3) + min(a2, b2 + b1) + min(a3, b3 + b2);
    int max_total = min(a1, b2) + min(a2, b3) + min(a3, b1);

    cout << n - min_total << " " << max_total << "\n";

    return 0;
}
